#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    // Find rightmost occurrence for each value in [0, max_value]
    int max_value = 0;
    for (int x : a) max_value = max(max_value, x);
    vector<int> rightmost(max_value + 2, -1); // +2 to handle MEX possibly being max_value+1

    for (int i = 0; i < n; ++i) {
        rightmost[a[i]] = i;
    }

    vector<int> res;
    int i = 0;
    while (i < n) {
        int mex = 0;
        int end = i;
        // Find the smallest MEX such that all [0, MEX-1] are present in [i, end]
        // For each value from 0 upwards, extend end to cover its rightmost occurrence
        while (true) {
            if (rightmost[mex] == -1 || rightmost[mex] < i) break;
            end = max(end, rightmost[mex]);
            ++mex;
        }
        res.push_back(mex);
        i = end + 1;
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}

