#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> freq(n + 2, 0);
    for (int x : a) if (x <= n) freq[x]++;

    int mex = 0;
    while (freq[mex]) ++mex;

    vector<int> res;
    int i = 0;
    while (i < n) {
        unordered_set<int> seen;
        int cur_mex = 0, cnt = 0;
        for (int j = i; j < n; ++j) {
            if (a[j] <= n) seen.insert(a[j]);
            while (seen.count(cur_mex)) ++cur_mex;
            ++cnt;
            if (cur_mex == mex) {
                res.push_back(mex);
                i = j + 1;
                // Update freq and recalculate mex for next segment
                for (int k = i - cnt; k < i; ++k) {
                    if (a[k] <= n) {
                        freq[a[k]]--;
                        if (freq[a[k]] == 0 && a[k] < mex) mex = a[k];
                    }
                }
                break;
            }
            if (j == n - 1) {
                // Last segment, can't reach current mex, so break
                res.push_back(cur_mex);
                i = n;
            }
        }
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}
